{
  "description": "The creature is a quadrupedal hybrid shown in right-facing profile with the overall size, shape, fur, head and limbs of a brown bear but with glossy beetle-like structures integrated into its body. It is covered in thick, shaggy brown fur that is darker on the legs and back and lighter tan on the muzzle, cheeks and underside. A single large, curved, glossy dark reddish-black horn rises from the top of the head, two large smooth domed shell plates sit on the back over the shoulders and mid-back, smaller segmented glossy plates cover the outer front legs, and a row of small round holes is visible in the fur on the side below the larger shell. It stands on four bear paws with visible claws and has a very short stubby tail.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head at the front of the body facing right, with an elongated muzzle, black nose with visible nostrils, small dark eyes, light tan fur on the muzzle and around the mouth, darker brown fur on the forehead and cheeks, and fine whiskers near the nose and mouth",
      "where": "at the anterior end of the body, connected to the thick furry neck"
    },
    {
      "part": "horns",
      "looks_like": "a single glossy dark brown to black curved horn with a smooth surface, a sharp tip curving forward and a small pointed tooth-like projection on the inner concave edge near the middle",
      "where": "emerging centrally from the top of the head between the two ears and arching upward and forward"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in dense brown fur with slightly lighter edges",
      "where": "on top of the head on either side of the base of the horn"
    },
    {
      "part": "legs",
      "looks_like": "four thick, columnar legs covered in long shaggy brown fur, the hind legs uniformly furry and the front legs bearing glossy dark segmented armor on the outer side",
      "where": "two front legs under the shoulder and two hind legs under the hips, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four large bear paws with dense fur on top and five long, curved, light tan to gray claws visible on each paw, with dark pads underneath partially visible",
      "where": "at the bottom of each leg, flat on the ground"
    },
    {
      "part": "tail",
      "looks_like": "a very short, stubby, rounded tail covered in the same shaggy brown fur as the body",
      "where": "at the rear of the body, protruding slightly from the rump"
    },
    {
      "part": "shell",
      "looks_like": "two large, smooth, highly glossy domed plates dark reddish-brown to black with visible suture lines and lighter reflections, one smaller and more triangular over the shoulders and one larger oval with fine longitudinal ridges over the mid-back",
      "where": "on the dorsal side of the body, one behind the neck over the shoulders and one centered over the back"
    },
    {
      "part": "plates",
      "looks_like": "segmented, overlapping glossy dark reddish-brown plates with pointed lower edges and a hard, chitinous appearance, arranged in rows of three to four segments",
      "where": "on the outer side of each front leg on the upper forelimb above the paw"
    },
    {
      "part": "markings",
      "looks_like": "a row of seven small circular holes with dark centers and thin light rims, resembling spiracles, set in the fur",
      "where": "in a horizontal line on the side of the body in the brown fur just below the ventral edge of the larger shell plate"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
